const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>Number(x.toFixed(6)).toLocaleString('ru-RU');
export function normaliseFoundation(raw={}){const s={n:20,eps:.1,offset:.2,step:.5};for(const [k,min,max,unit] of [['n',1,200,1],['offset',-1,1,.05],['step',.01,1,.01]])if(typeof raw?.[k]==='number'&&Number.isFinite(raw[k]))s[k]=Math.round(Math.max(min,Math.min(max,raw[k]))/unit)*unit;if([.5,.2,.1,.05,.01].includes(raw?.eps))s.eps=raw.eps;return s;}
const slider=(key,label,min,max,step,value)=>'<label class="model-control">'+label+' <output data-foundation-value="'+key+'">'+fmt(value)+'</output><input aria-label="'+label+'" data-foundation-field="'+key+'" type="range" min="'+min+'" max="'+max+'" step="'+step+'" value="'+value+'"></label>';
const epsSelect=s=>'<label>Точность ε<select data-foundation-field="eps">'+[.5,.2,.1,.05,.01].map(v=>'<option value="'+v+'" '+(v===s.eps?'selected':'')+'>'+fmt(v)+'</option>').join('')+'</select></label>';
export function foundationOutput(id,s){
 if(id==='real'){const dots=Array.from({length:s.n},(_,i)=>'<circle cx="'+(45+310*(1-1/(i+1)))+'" cy="130" r="4" fill="#174c43"/>').join('');return '<svg viewBox="0 0 400 210" role="img" aria-label="Члены множества 1−1/n приближаются к супремуму 1"><path d="M35 130H370" stroke="#758c7c"/>'+dots+'<circle cx="355" cy="130" r="7" fill="white" stroke="#b64d32"/><text x="40" y="170">0</text><text x="350" y="170">1</text></svg><div class="lab-conclusion"><strong>max первых '+s.n+' членов = '+fmt(1-1/s.n)+'</strong><p>У бесконечного множества A={1−1/n:n≥1} sup A=1, а максимума нет. У конечного набора первых N членов максимум 1−1/N существует. Увеличение числа показанных членов не добавляет точку 1 в A.</p></div>';}
 if(id==='sequences'){const N=Math.max(1,Math.floor(Number((1/s.eps).toFixed(8))));return '<div class="formula">aₙ=2+1/n; A=2; ε='+fmt(s.eps)+'</div><div class="lab-conclusion"><strong>Подходит N='+N+'; проверяем n='+s.n+'</strong><p>|aₙ−2|=1/n='+fmt(1/s.n)+'. '+(s.n>N?'n>N, поэтому ошибка строго меньше ε.':1/s.n<s.eps?'Для выбранного n ошибка меньше ε.':'Для выбранного n ошибка не меньше ε; этот номер не лежит в гарантированном хвосте.')+' Условие относится ко всем n>N, а не только к одному члену.</p></div>';}
 if(id==='limits'){const delta=s.eps/2,h=s.offset;return '<div class="formula">f(x)=2x+1; a=1; L=3; δ=ε/2='+fmt(delta)+'</div><div class="lab-conclusion"><strong>x=1+h='+fmt(1+h)+'; |f(x)−3|=2|h|='+fmt(2*Math.abs(h))+'</strong><p>'+(h===0?'h=0: сама точка a исключена из условия предела.':Math.abs(h)<delta?'0<|h|<δ: значение удовлетворяет требуемой оценке.':'|h|≥δ: выбранный аргумент вне гарантированной проколотой окрестности.')+' Для каждого ε выбирается δ, после чего утверждение должно выполняться для всех допустимых x.</p></div>';}
 return '<div class="formula">f(x)=x²; a=1; h='+fmt(s.step)+'</div><div class="lab-conclusion"><strong>[f(1+h)−f(1)]/h=2+h='+fmt(2+s.step)+'</strong><p>При h→0 отношение стремится к 2. Выбранное конечное h даёт секущую; производная f′(1)=2 является пределом этих отношений. Ошибка относительно предела равна h='+fmt(s.step)+'.</p></div>';
}
export function foundationLab(c,s){let controls='';if(c.id==='real')controls=slider('n','Число показанных членов N',1,200,1,s.n);if(c.id==='sequences')controls=epsSelect(s)+slider('n','Номер члена n',1,200,1,s.n);if(c.id==='limits')controls=epsSelect(s)+slider('offset','Приращение h=x−1',-1,1,.05,s.offset);if(c.id==='derivatives')controls=slider('step','Приращение h',.01,1,.01,s.step);return '<p class="eyebrow">Раздел '+c.program+' программы · примеры</p>'+(controls?'<h2>Проверка определения</h2><section class="lab-panel advanced-model"><div class="lab-controls">'+controls+'</div><div id="foundation-model-output" aria-live="polite">'+foundationOutput(c.id,s)+'</div></section>':'')+'<h2 class="section-space">Разобранные задачи</h2>'+c.workedExamples.map(e=>'<details class="deep worked-example" open><summary>'+esc(e.title)+'</summary><p>'+esc(e.statement)+'</p><ol>'+e.steps.map(step=>'<li>'+esc(step)+'</li>').join('')+'</ol><div class="formula">'+esc(e.result)+'</div></details>').join('');}
